{
  s16 fire_par_3;
  s16 unk_1;
  s16 diff_x;
  s16 diff_y;
  u8 x_gt_0;
  u8 y_gt_0;
  diff_x = (ray_zdc_x + (ray_zdc_w >> 1)) - in_x;
  diff_y = (ray_zdc_h + (ray_zdc_y >> 1)) - in_y;
  x_gt_0 = diff_x > 0;
  y_gt_0 = diff_y > 0;
  if (!x_gt_0)
    diff_x = -diff_x;
  if (!y_gt_0)
    diff_y = -diff_y;
  if (diff_x > 200)
  {
    diff_x = ashr16(diff_x, 1);
    diff_y = ashr16(diff_y, 1);
  }
  if (diff_y == 0)
  {
    if (x_gt_0)
      fire_par_3 = 27;
    else
      if (diff_x != 0)
      fire_par_3 = 9;
    else
      fire_par_3 = -1;
  }
  else
  {
    unk_1 = (diff_x * 45) / diff_y;
    if (x_gt_0)
    {
      if (y_gt_0)
      {
        if (unk_1 > 255)
          fire_par_3 = 27;
        else
          fire_par_3 = 27 + N_anim[unk_1];
      }
      else
      {
        if (unk_1 > 255)
          fire_par_3 = 0;
        else
          fire_par_3 = N_anim[unk_1];
      }
    }
    else
      if (y_gt_0)
    {
      if (unk_1 > 255)
        fire_par_3 = 18;
      else
        fire_par_3 = 18 + N_anim[unk_1];
    }
    else
    {
      if (unk_1 > 255)
        fire_par_3 = 9;
      else
        fire_par_3 = 9 + N_anim[unk_1];
    }
  }
  DO_REDEYE_FIRE(in_x, in_y, fire_par_3);
}

