{
  s16 obj_sub_etat;
  s32 speed;
  u8 horl_0;
  s16 offs_bx;
  s16 offs_by;
  {
    s16 state_snapshot;
    s16 *state_ptr = &state_snapshot;
    *state_ptr = obj->sub_etat;
    obj_sub_etat = state_snapshot;
  }
  {
    u8 clock_tick;
    clock_tick = horloge[obj->eta[obj->main_etat][obj->sub_etat].anim_speed & 0x0f];
    horl_0 = clock_tick == 0;
  }
  switch (obj_sub_etat)
  {
    default:
      break;

    case 2:
      if ((obj->anim_frame == 14) && horl_0)
      DO_BAT_LEFT_RIGHT_FLASH(obj);
      break;

    case 5:
      if (obj->anim_frame == 22)
    {
      if (myRand(1) == 0)
        skipToLabel(obj, 2, 1);
      else
        skipToLabel(obj, 3, 1);
      return;
    }
      break;

    case 3:

    case 4:
      if ((obj->anim_frame == 19) && horl_0)
    {
      bat_nb_frap++;
      if (obj_sub_etat == 4)
        DO_BAT_RIGHT_FLASH(obj);
      if (obj_sub_etat == 3)
        DO_BAT_LEFT_FLASH(obj);
    }
      break;

    case 6:

    case 7:
      if (obj->anim_frame == 20)
    {
      switch (bat_nb_frap)
      {
        case 1:
          set_sub_etat(obj, 11);
          break;

        case 3:
          set_sub_etat(obj, 11);
          bat_nb_frap = 0;
          break;

        default:
          if (obj_sub_etat == 6)
          skipToLabel(obj, 3, 1);
        else
          skipToLabel(obj, 2, 1);
          break;

      }

    }
      break;

    case 8:
      if (bat_dir(obj))
      skipToLabel(obj, 4, 1);
    else
      skipToLabel(obj, 5, 1);
      break;

    case 11:
      if (bat_dir(obj))
      skipToLabel(obj, 6, 1);
    else
      skipToLabel(obj, 7, 1);
      break;

    case 9:

    case 10:

    case 12:

    case 13:
      if (obj->cmd == GO_SPEED)
    {
      switch (obj_sub_etat)
      {
        case 10:

        case 13:
          speed = obj->iframes_timer;
          obj->speed_x = Abs(speed);
          obj->speed_x = -obj->speed_x;
          break;

        case 12:

        case 9:
          speed = obj->iframes_timer;
          obj->speed_x = Abs(speed);
          break;

      }

      obj->speed_y = obj->follow_id;
    }
      offs_bx = obj->offset_bx;
      offs_by = obj->offset_by;
      if (test_allowed(obj, offs_bx, offs_by) && on_block_chdir(obj, offs_bx, offs_by))
    {
      switch (obj_sub_etat)
      {
        case 10:
          obj->sub_etat = 9;
          break;

        case 9:
          obj->sub_etat = 10;
          break;

        case 13:
          obj->sub_etat = 12;
          break;

        case 12:
          obj->sub_etat = 13;
          break;

      }

    }
      break;

  }

}
